import { defineConfig } from 'drizzle-kit';

/**
 * Drizzle Kit is used here for `pnpm --filter @yusr/api db:studio` (a browser view of the data).
 *
 * Migrations are NOT generated by Drizzle Kit: they are hand-written SQL in src/db/migrations
 * (the ledger invariants, append-only triggers and the case-status backstop are PostgreSQL features)
 * and applied by src/db/migrate.ts (`pnpm db:migrate`). src/db/schema.ts mirrors them for typed
 * queries. `drizzle-kit generate` writes to ./drizzle-draft (git-ignored) — a draft to compare
 * against when you write the next numbered migration by hand, never applied as is.
 */
try {
  process.loadEnvFile('.env');
} catch {
  // No .env file: use the environment (or the development default below).
}

export default defineConfig({
  dialect: 'postgresql',
  schema: './src/db/schema.ts',
  out: './drizzle-draft',
  dbCredentials: { url: process.env['DATABASE_URL'] ?? 'postgres://yusr:yusr@localhost:5432/yusr' },
  strict: true,
  verbose: true,
});
